// sun_sweep 0..3. Always on: hanging lamps sway out of phase, dust in the shafts, stove glow, steam, clock, jackets, hoisted engine.

export function stateFromEvents(events, f, base = {}) {             // { f0, f1, obj, from, to }: smootherstep, hold the last value
  const s = { ...base }, by = {};
  for (const e of events || []) (by[e.obj] ||= []).push(e);
  for (const [k, list] of Object.entries(by)) {
    list.sort((a, b) => a.f0 - b.f0); let v = s[k] ?? list[0].from ?? 0;
    for (const e of list) { if (f < e.f0) break; const a = e.from ?? v, u = e.f1 > e.f0 ? Math.min(1, (f - e.f0) / (e.f1 - e.f0)) : 1; v = a + (e.to - a) * (u * u * u * (u * (u * 6 - 15) + 10)); }
    s[k] = v;
  }
  return s;
}

