    const first = Array.from({ length: N1 }, (_, i) => i).sort((a, b) => baseW[b][0] - baseW[a][0]); if (PF.hand_near) { let bi = 0, bd = 1e9; first.forEach((i, j) => { const d = Math.hypot(baseW[i][0] - PF.hand_near[0], baseW[i][2] - PF.hand_near[1]); if (d < bd) { bd = d; bi = j; } }); first.unshift(first.splice(bi, 1)[0]); } console.warn('pin_fire first pin ' + JSON.stringify(baseW[first[0]].map(v => +v.toFixed(3)))); let k = 0; hitF[first[k++]] = PF.hand; muz[first[0]] = null;   /* the one put in by hand does not fly */
